//! 🏭️ Reserved work borrows its retained request through one original concrete job and paid terminal closure.
use super::{ArtifactReservedToolJobRequest,ArtifactReservedJob};
use crate::ArtifactApp;
use semio_framework_job::{StepContext,OriginalTurnFailure,OriginalJobReturnClaim,InteractiveJobStep,InteractiveJobCloseStep,JobOutcomeBorrow,JobOutcomeDescriptor,JobOutcomeView,InteractiveJob};
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,RetainedCloneProgress,retained_clone::RetainedCloneClose};
use std::mem::{ManuallyDrop,size_of};
pub trait ArtifactReservedWork<A:ArtifactApp>:Default+Send+'static{
 fn step<'a>(&'a mut self,request:&'a mut ArtifactReservedToolJobRequest<A>,cx:&mut StepContext<'_>,claim:&mut OriginalJobReturnClaim<'_>)->InteractiveJobStep<'a>;
 fn borrow_outcome<'a>(&'a self,descriptor:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>;
 fn begin_close(&mut self);
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>;
 fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>;
 fn terminal_is_empty(&self)->bool;
}
pub struct ArtifactReservedRequestJob<A:ArtifactApp,W:ArtifactReservedWork<A>>{source:semio_framework::action_bus::OriginalToolSourceBinding,decoder:(u64,u64),request:ManuallyDrop<Option<ArtifactReservedToolJobRequest<A>>>,work:ManuallyDrop<Option<W>>,retirement:RetainedCloneClose,closing:bool}
pub fn admit_reserved_work<A:ArtifactApp,W:ArtifactReservedWork<A>>(source:&mut Option<ArtifactReservedToolJobRequest<A>>,receiving:&mut Option<Box<dyn ArtifactReservedJob+Send>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
 cx.original_source_parent()?;if let Some(body)=receiving.as_ref(){if source.is_some(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original reserved work receiver is already occupied").into())}let owner=(&**body as &dyn std::any::Any).downcast_ref::<ArtifactReservedRequestJob<A,W>>().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"original reserved receiver has another concrete work type"))?;if !owner.source.matches(cx)||cx.native_receiving_identity()!=Some(owner.decoder){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original reserved receiver belongs to another source or decoder").into())}return Ok(true)}
 let original=source.as_ref().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"original reserved request is absent"))?;if !original.source_binding.matches(cx){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"reserved work requires its unchanged original source").into())}
 let binding=original.source_binding;let bytes=size_of::<ArtifactReservedRequestJob<A,W>>();
 semio_framework_job::admit_original_construction(cx,receiving,semio_framework_job::OriginalConstructionDemand{items:1,copy_bytes:bytes,capacity_bytes:bytes,release_bytes:0,depth:1},|control|{
  let result=(||{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(||ValueError::literal(ValueRefusalKind::UnsupportedOwner,"reserved work requires its original decoder recipient"))?);let pointer=std::ptr::NonNull::new(unsafe{std::alloc::alloc(std::alloc::Layout::new::<ArtifactReservedRequestJob<A,W>>())}.cast::<ArtifactReservedRequestJob<A,W>>()).ok_or_else(||ValueError::literal(ValueRefusalKind::AllocationFailed,"original reserved work frame allocation refused"))?;let owner=ArtifactReservedRequestJob{source:binding,decoder,request:ManuallyDrop::new(source.take()),work:ManuallyDrop::new(Some(W::default())),retirement:Default::default(),closing:false};let body:Box<dyn ArtifactReservedJob+Send>=unsafe{pointer.as_ptr().write(owner);Box::from_raw(pointer.as_ptr())};Ok((body,RetainedCloneProgress{copied_items:1,copied_bytes:bytes,retained_capacity_bytes:bytes,..Default::default()}))})();semio_framework_value::RetainedWorkOutcome{work:1,result}
 })
}
impl<A:ArtifactApp,W:ArtifactReservedWork<A>> ArtifactReservedRequestJob<A,W>{
 fn demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(work)=self.work.as_ref(){if !work.terminal_is_empty(){return work.close_demands(body)}return Ok(RetirementDemand{depth:1,..Default::default()})}self.retirement.next_owner_demands::<ArtifactReservedToolJobRequest<A>>(self.request.is_some(),&None,body)}
}
impl<A:ArtifactApp,W:ArtifactReservedWork<A>> InteractiveJob for ArtifactReservedRequestJob<A,W>{
 fn step<'a>(&'a mut self,cx:&mut StepContext<'_>,claim:&mut OriginalJobReturnClaim<'_>)->InteractiveJobStep<'a>{if !self.source.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return InteractiveJobStep::from_callback(Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"reserved job refused another original caller").into()))}if self.closing||cx.is_cancelled(){return InteractiveJobStep::from_callback(JobOutcomeBorrow::admit_cancelled(cx).map_err(Into::into))}let Some(request)=self.request.as_mut()else{return InteractiveJobStep::from_callback(Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"reserved job lost its original request").into()))};if !request.source_binding.matches(cx){return InteractiveJobStep::from_callback(Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"reserved job refused another original caller").into()))}self.work.as_mut().unwrap().step(request,cx,claim)}
 fn borrow_outcome<'a>(&'a self,descriptor:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{match descriptor.kind(){semio_framework_job::JobOutcomeKind::Yield=>descriptor.yielded(),semio_framework_job::JobOutcomeKind::Cancelled=>descriptor.cancelled(),_=>if let Some(work)=self.work.as_ref(){work.borrow_outcome(descriptor)}else{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"reserved work retired before its outcome handoff"))}}}
 fn begin_close(&mut self){self.closing=true;}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.demands(0)?.copy_bytes)}
 fn next_close_capacity_byte_demand(&self,body:usize)->Result<usize,ValueError>{Ok(self.demands(body)?.capacity_bytes)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.demands(0)?.release_bytes)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(self.demands(0)?.depth)}
 fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{cx.original_source_parent()?;if !self.source.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"reserved job close refused another original caller").into())}self.begin_close();if self.terminal_is_empty(){return Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}if let Some(work)=self.work.as_mut(){work.begin_close();if !work.terminal_is_empty(){return work.close_step(cx)}return semio_framework_job::close_original_retained_step(cx,RetirementDemand{depth:1,..Default::default()},|_|{self.work.take();semio_framework_value::RetainedWorkOutcome{result:Ok(semio_framework_value::RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()})),work:1}})}let demand=self.demands(cx.retained_grant().maximum_copy_bytes)?;let step=semio_framework_job::close_original_retained_step(cx,demand,|grant|if self.retirement.is_empty(){let turn=self.retirement.begin_granted(&mut self.request,grant);semio_framework_value::RetainedWorkOutcome{result:turn.result.map(|step|step.unwrap_or(semio_framework_value::RetainedCloneStep::Complete(Default::default()))),work:turn.work}}else{self.retirement.step_granted(grant)})?;Ok(if self.terminal_is_empty(){InteractiveJobCloseStep::Complete{progress:step.progress()}}else{step})}
 fn terminal_is_empty(&self)->bool{self.request.is_none()&&self.work.is_none()&&self.retirement.is_empty()}
}
impl<A:ArtifactApp,W:ArtifactReservedWork<A>> ArtifactReservedJob for ArtifactReservedRequestJob<A,W>{}
impl<A:ArtifactApp,W:ArtifactReservedWork<A>> Drop for ArtifactReservedRequestJob<A,W>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"reserved request and private work require original funded close");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.request);ManuallyDrop::drop(&mut self.work)}}}}
